insert into vocab_decks (slug, title, description, categories)
select
  'fce',
  'Từ vựng FCE (B2 First)',
  '1000 từ và cụm từ trọng tâm cho Cambridge B2 First - Use of English Part 1-4: collocation, phrasal verb, giới từ và word formation.',
  array(select jsonb_array_elements_text($fce$["Cụm động từ", "Collocations", "Giới từ đi kèm", "Thành ngữ & cụm cố định", "Từ nối", "Họ từ (Word formation)", "Công việc & tiền bạc", "Giáo dục", "Sức khỏe", "Môi trường & thiên nhiên", "Công nghệ & khoa học", "Du lịch & giao thông", "Truyền thông & nghệ thuật", "Tính cách & cảm xúc", "Quan hệ & xã hội", "Nhà cửa & đời sống", "Ẩm thực", "Thể thao & giải trí", "Tội phạm & pháp luật"]$fce$::jsonb))
on conflict (slug) do nothing;

insert into vocab_deck_words (deck_id, position, word, type, meaning_vi, example, category)
select d.id, w.id, w.word, w.type, w.meaning_vi, w.example, w.category
from vocab_decks d,
  jsonb_to_recordset($fce$[{"id":1,"word":"break down","type":"phr v","meaning_vi":"hỏng (máy); suy sụp","example":"Our car broke down on the motorway.","category":"Cụm động từ"},{"id":2,"word":"break up (with)","type":"phr v","meaning_vi":"chia tay","example":"She broke up with her boyfriend last month.","category":"Cụm động từ"},{"id":3,"word":"break into","type":"phr v","meaning_vi":"đột nhập","example":"Someone broke into our house last night.","category":"Cụm động từ"},{"id":4,"word":"break out","type":"phr v","meaning_vi":"bùng nổ (chiến tranh, dịch bệnh, hỏa hoạn)","example":"A fire broke out in the kitchen.","category":"Cụm động từ"},{"id":5,"word":"bring up","type":"phr v","meaning_vi":"nuôi nấng; nêu ra (vấn đề)","example":"She was brought up by her grandparents.","category":"Cụm động từ"},{"id":6,"word":"bring about","type":"phr v","meaning_vi":"gây ra, mang lại","example":"The internet has brought about huge changes.","category":"Cụm động từ"},{"id":7,"word":"bring back","type":"phr v","meaning_vi":"gợi lại (ký ức); mang trả lại","example":"This song brings back memories.","category":"Cụm động từ"},{"id":8,"word":"call off","type":"phr v","meaning_vi":"hủy bỏ","example":"The match was called off because of rain.","category":"Cụm động từ"},{"id":9,"word":"call back","type":"phr v","meaning_vi":"gọi lại","example":"I'll call you back later.","category":"Cụm động từ"},{"id":10,"word":"calm down","type":"phr v","meaning_vi":"bình tĩnh lại","example":"Calm down and tell me what happened.","category":"Cụm động từ"},{"id":11,"word":"carry on","type":"phr v","meaning_vi":"tiếp tục","example":"Carry on with your work.","category":"Cụm động từ"},{"id":12,"word":"carry out","type":"phr v","meaning_vi":"tiến hành, thực hiện","example":"Scientists carried out an experiment.","category":"Cụm động từ"},{"id":13,"word":"catch up (with)","type":"phr v","meaning_vi":"bắt kịp","example":"I need to catch up with my classmates.","category":"Cụm động từ"},{"id":14,"word":"check in","type":"phr v","meaning_vi":"làm thủ tục (khách sạn, sân bay)","example":"We checked in at the hotel at 3 pm.","category":"Cụm động từ"},{"id":15,"word":"cheer up","type":"phr v","meaning_vi":"làm vui lên, vui lên","example":"Cheer up! It's not the end of the world.","category":"Cụm động từ"},{"id":16,"word":"come across","type":"phr v","meaning_vi":"tình cờ gặp/thấy","example":"I came across an old photo in the drawer.","category":"Cụm động từ"},{"id":17,"word":"come up with","type":"phr v","meaning_vi":"nghĩ ra (ý tưởng)","example":"She came up with a brilliant idea.","category":"Cụm động từ"},{"id":18,"word":"come down with","type":"phr v","meaning_vi":"bị ốm (bệnh nhẹ)","example":"He came down with the flu.","category":"Cụm động từ"},{"id":19,"word":"come round","type":"phr v","meaning_vi":"ghé thăm; tỉnh lại","example":"Come round for dinner on Friday.","category":"Cụm động từ"},{"id":20,"word":"count on","type":"phr v","meaning_vi":"tin cậy, trông cậy vào","example":"You can count on me.","category":"Cụm động từ"},{"id":21,"word":"cut down on","type":"phr v","meaning_vi":"cắt giảm","example":"I'm trying to cut down on sugar.","category":"Cụm động từ"},{"id":22,"word":"cut off","type":"phr v","meaning_vi":"cắt (điện, nước); cô lập","example":"The village was cut off by the flood.","category":"Cụm động từ"},{"id":23,"word":"deal with","type":"phr v","meaning_vi":"giải quyết, xử lý","example":"She deals with customer complaints.","category":"Cụm động từ"},{"id":24,"word":"drop out (of)","type":"phr v","meaning_vi":"bỏ học, bỏ ngang","example":"He dropped out of university.","category":"Cụm động từ"},{"id":25,"word":"drop in","type":"phr v","meaning_vi":"ghé qua","example":"Drop in whenever you're in town.","category":"Cụm động từ"},{"id":26,"word":"end up","type":"phr v","meaning_vi":"rốt cuộc, cuối cùng thì","example":"We ended up staying at home.","category":"Cụm động từ"},{"id":27,"word":"fall out (with)","type":"phr v","meaning_vi":"cãi nhau, bất hòa","example":"I fell out with my best friend.","category":"Cụm động từ"},{"id":28,"word":"fall behind","type":"phr v","meaning_vi":"tụt lại phía sau","example":"Don't fall behind with your homework.","category":"Cụm động từ"},{"id":29,"word":"figure out","type":"phr v","meaning_vi":"hiểu ra, tìm ra","example":"I can't figure out how this works.","category":"Cụm động từ"},{"id":30,"word":"fill in","type":"phr v","meaning_vi":"điền (mẫu đơn)","example":"Please fill in this form.","category":"Cụm động từ"},{"id":31,"word":"find out","type":"phr v","meaning_vi":"phát hiện, tìm hiểu","example":"I found out the truth yesterday.","category":"Cụm động từ"},{"id":32,"word":"get on (with)","type":"phr v","meaning_vi":"hòa hợp với","example":"I get on well with my colleagues.","category":"Cụm động từ"},{"id":33,"word":"get over","type":"phr v","meaning_vi":"vượt qua, hồi phục","example":"It took her months to get over the shock.","category":"Cụm động từ"},{"id":34,"word":"get along","type":"phr v","meaning_vi":"hòa thuận; xoay xở","example":"How are you getting along in your new job?","category":"Cụm động từ"},{"id":35,"word":"get away with","type":"phr v","meaning_vi":"thoát tội, làm sai mà không bị phạt","example":"He cheated and got away with it.","category":"Cụm động từ"},{"id":36,"word":"get rid of","type":"phr v","meaning_vi":"loại bỏ, vứt bỏ","example":"I got rid of my old clothes.","category":"Cụm động từ"},{"id":37,"word":"get by","type":"phr v","meaning_vi":"xoay xở (đủ sống, đủ dùng)","example":"I can get by in French.","category":"Cụm động từ"},{"id":38,"word":"get across","type":"phr v","meaning_vi":"truyền đạt (ý)","example":"He found it hard to get his message across.","category":"Cụm động từ"},{"id":39,"word":"give up","type":"phr v","meaning_vi":"từ bỏ","example":"She gave up smoking last year.","category":"Cụm động từ"},{"id":40,"word":"give in","type":"phr v","meaning_vi":"nhượng bộ, chịu thua","example":"He finally gave in and said yes.","category":"Cụm động từ"},{"id":41,"word":"give away","type":"phr v","meaning_vi":"cho đi; tiết lộ","example":"Don't give away the ending!","category":"Cụm động từ"},{"id":42,"word":"go off","type":"phr v","meaning_vi":"(chuông) reo; (thức ăn) ôi thiu; nổ","example":"The milk has gone off.","category":"Cụm động từ"},{"id":43,"word":"go on","type":"phr v","meaning_vi":"tiếp tục; xảy ra","example":"What's going on here?","category":"Cụm động từ"},{"id":44,"word":"go through","type":"phr v","meaning_vi":"trải qua (khó khăn); xem kỹ","example":"She's going through a difficult time.","category":"Cụm động từ"},{"id":45,"word":"go over","type":"phr v","meaning_vi":"xem lại, ôn lại","example":"Let's go over the plan again.","category":"Cụm động từ"},{"id":46,"word":"go ahead","type":"phr v","meaning_vi":"tiến hành, cứ làm đi","example":"The concert will go ahead despite the rain.","category":"Cụm động từ"},{"id":47,"word":"grow up","type":"phr v","meaning_vi":"lớn lên","example":"I grew up in a small town.","category":"Cụm động từ"},{"id":48,"word":"hand in","type":"phr v","meaning_vi":"nộp (bài)","example":"Hand in your essays by Friday.","category":"Cụm động từ"},{"id":49,"word":"hang out","type":"phr v","meaning_vi":"đi chơi, tụ tập","example":"We usually hang out at the café.","category":"Cụm động từ"},{"id":50,"word":"hold on","type":"phr v","meaning_vi":"chờ một chút; giữ chặt","example":"Hold on, I'll get a pen.","category":"Cụm động từ"},{"id":51,"word":"hold up","type":"phr v","meaning_vi":"làm chậm trễ","example":"We were held up in traffic.","category":"Cụm động từ"},{"id":52,"word":"keep up with","type":"phr v","meaning_vi":"theo kịp","example":"It's hard to keep up with the news.","category":"Cụm động từ"},{"id":53,"word":"keep on","type":"phr v","meaning_vi":"tiếp tục (làm gì)","example":"He kept on talking during the film.","category":"Cụm động từ"},{"id":54,"word":"let down","type":"phr v","meaning_vi":"làm thất vọng","example":"I won't let you down.","category":"Cụm động từ"},{"id":55,"word":"look after","type":"phr v","meaning_vi":"chăm sóc","example":"Who looks after your dog when you're away?","category":"Cụm động từ"},{"id":56,"word":"look forward to","type":"phr v","meaning_vi":"mong đợi","example":"I'm looking forward to seeing you.","category":"Cụm động từ"},{"id":57,"word":"look into","type":"phr v","meaning_vi":"điều tra, xem xét","example":"The police are looking into the case.","category":"Cụm động từ"},{"id":58,"word":"look up","type":"phr v","meaning_vi":"tra cứu","example":"Look up the word in a dictionary.","category":"Cụm động từ"},{"id":59,"word":"look up to","type":"phr v","meaning_vi":"kính trọng, ngưỡng mộ","example":"She looks up to her older sister.","category":"Cụm động từ"},{"id":60,"word":"look down on","type":"phr v","meaning_vi":"coi thường","example":"Don't look down on people with less money.","category":"Cụm động từ"},{"id":61,"word":"make up","type":"phr v","meaning_vi":"bịa ra; làm hòa; trang điểm","example":"He made up an excuse for being late.","category":"Cụm động từ"},{"id":62,"word":"make up for","type":"phr v","meaning_vi":"bù đắp","example":"I'll make up for lost time.","category":"Cụm động từ"},{"id":63,"word":"make out","type":"phr v","meaning_vi":"nhìn/nghe ra được, hiểu được","example":"I couldn't make out what he said.","category":"Cụm động từ"},{"id":64,"word":"pass away","type":"phr v","meaning_vi":"qua đời","example":"Her grandfather passed away last year.","category":"Cụm động từ"},{"id":65,"word":"pass out","type":"phr v","meaning_vi":"ngất xỉu","example":"He passed out from the heat.","category":"Cụm động từ"},{"id":66,"word":"pick up","type":"phr v","meaning_vi":"đón; nhặt; học lỏm","example":"I picked up some Spanish on holiday.","category":"Cụm động từ"},{"id":67,"word":"point out","type":"phr v","meaning_vi":"chỉ ra","example":"She pointed out my mistake.","category":"Cụm động từ"},{"id":68,"word":"put off","type":"phr v","meaning_vi":"trì hoãn; làm mất hứng","example":"Don't put off your homework.","category":"Cụm động từ"},{"id":69,"word":"put up with","type":"phr v","meaning_vi":"chịu đựng","example":"I can't put up with the noise any more.","category":"Cụm động từ"},{"id":70,"word":"put on","type":"phr v","meaning_vi":"mặc vào; tăng (cân)","example":"He's put on a lot of weight.","category":"Cụm động từ"},{"id":71,"word":"put out","type":"phr v","meaning_vi":"dập tắt (lửa)","example":"Firefighters put out the fire.","category":"Cụm động từ"},{"id":72,"word":"put forward","type":"phr v","meaning_vi":"đề xuất","example":"She put forward a new proposal.","category":"Cụm động từ"},{"id":73,"word":"run out of","type":"phr v","meaning_vi":"hết, cạn","example":"We've run out of milk.","category":"Cụm động từ"},{"id":74,"word":"run into","type":"phr v","meaning_vi":"tình cờ gặp","example":"I ran into an old friend at the station.","category":"Cụm động từ"},{"id":75,"word":"set up","type":"phr v","meaning_vi":"thành lập, thiết lập","example":"He set up his own company.","category":"Cụm động từ"},{"id":76,"word":"set off","type":"phr v","meaning_vi":"khởi hành","example":"We set off early in the morning.","category":"Cụm động từ"},{"id":77,"word":"settle down","type":"phr v","meaning_vi":"ổn định (cuộc sống)","example":"They want to settle down and have children.","category":"Cụm động từ"},{"id":78,"word":"show off","type":"phr v","meaning_vi":"khoe khoang","example":"He's always showing off his new car.","category":"Cụm động từ"},{"id":79,"word":"show up","type":"phr v","meaning_vi":"xuất hiện, có mặt","example":"Only five people showed up.","category":"Cụm động từ"},{"id":80,"word":"sort out","type":"phr v","meaning_vi":"giải quyết, sắp xếp","example":"We need to sort out this problem.","category":"Cụm động từ"},{"id":81,"word":"stand for","type":"phr v","meaning_vi":"viết tắt cho; ủng hộ, đại diện","example":"What does BBC stand for?","category":"Cụm động từ"},{"id":82,"word":"stand out","type":"phr v","meaning_vi":"nổi bật","example":"Her talent really stands out.","category":"Cụm động từ"},{"id":83,"word":"stand up for","type":"phr v","meaning_vi":"bênh vực, đứng lên bảo vệ","example":"Stand up for what you believe in.","category":"Cụm động từ"},{"id":84,"word":"take after","type":"phr v","meaning_vi":"giống (người thân)","example":"She takes after her mother.","category":"Cụm động từ"},{"id":85,"word":"take up","type":"phr v","meaning_vi":"bắt đầu (sở thích); chiếm (chỗ, thời gian)","example":"I've taken up yoga.","category":"Cụm động từ"},{"id":86,"word":"take off","type":"phr v","meaning_vi":"cất cánh; cởi ra; thành công nhanh","example":"The plane took off on time.","category":"Cụm động từ"},{"id":87,"word":"take over","type":"phr v","meaning_vi":"tiếp quản","example":"A big company took over the firm.","category":"Cụm động từ"},{"id":88,"word":"take on","type":"phr v","meaning_vi":"đảm nhận; tuyển dụng","example":"She took on too much work.","category":"Cụm động từ"},{"id":89,"word":"take in","type":"phr v","meaning_vi":"hiểu, tiếp thu; lừa gạt","example":"It was too much information to take in.","category":"Cụm động từ"},{"id":90,"word":"turn down","type":"phr v","meaning_vi":"từ chối; vặn nhỏ","example":"She turned down the job offer.","category":"Cụm động từ"},{"id":91,"word":"turn up","type":"phr v","meaning_vi":"xuất hiện; vặn to","example":"He turned up late as usual.","category":"Cụm động từ"},{"id":92,"word":"turn out","type":"phr v","meaning_vi":"hóa ra là","example":"The film turned out to be great.","category":"Cụm động từ"},{"id":93,"word":"turn into","type":"phr v","meaning_vi":"biến thành","example":"The caterpillar turned into a butterfly.","category":"Cụm động từ"},{"id":94,"word":"work out","type":"phr v","meaning_vi":"tập thể dục; tìm ra; diễn ra tốt","example":"I work out at the gym three times a week.","category":"Cụm động từ"},{"id":95,"word":"wear out","type":"phr v","meaning_vi":"làm mòn; làm kiệt sức","example":"My shoes are worn out.","category":"Cụm động từ"},{"id":96,"word":"wr